const _settingsBase=renderSettingsPage;
renderSettingsPage=function(){const access=`<div class="panel role-access-detail"><div class="panel-title"><div><h3>Akses Role Anda</h3><span>${escapeHtml(ROLE_LABELS[currentRole()]||currentRole())}</span></div></div><p>${escapeHtml(roleAccessSummary())}</p></div>`;return access+_settingsBase().replace(/V1\.9\.3[^<]*/g,'V1.16 · Shift, Refund, Opname, Barcode, Promo, Recipe & CRM')};

// ---------- Role-aware navigation (desktop + mobile) ----------
function openMobileMoreMenu(extra){
  openModal(`<div class="modal-title"><h2>Menu Lainnya</h2><button class="modal-close">×</button></div><div class="mobile-more-grid">${extra.map(n=>`<button type="button" class="quick-card mobile-more-link" data-mobile-nav="${escapeAttr(n.id)}"><strong>${n.icon} ${escapeHtml(n.mobileLabel||n.label)}</strong><span>Buka menu</span></button>`).join('')}</div><div class="modal-actions"><button type="button" class="primary modal-close">Tutup</button></div>`);
  $$('.mobile-more-link').forEach(b=>b.onclick=()=>{closeModal();navigate(b.dataset.mobileNav)});
}
renderNav=function(){
  let visible=NAV.filter(n=>n.id==='systemAdmin'?(state.mode==='cloud'&&state.isSystemAdmin):can(NAV_PERMISSION[n.id]));
  const role=currentRole();
  // Finance reads sales data for reports/payment but should not be presented with a cashier menu.
  if(role==='finance')visible=visible.filter(n=>n.id!=='sales');
  if(!visible.some(n=>n.id===state.page))state.page=state.isSystemAdmin&&!state.businesses.length?'systemAdmin':'dashboard';
  $('#desktopNav').innerHTML=visible.map(n=>{const label=role==='warehouse'&&n.id==='sales'?'Pengiriman':n.label;return `<button class="nav-item ${state.page===n.id?'active':''}" data-nav="${n.id}"><span class="nav-icon">${n.icon}</span>${escapeHtml(label)}</button>`}).join('');
  const primaryByRole={
    owner:['dashboard','sales','products','reports','crm'],
    admin:['dashboard','sales','products','reports','crm'],
    cashier:['dashboard','sales','products','crm','settings'],
    finance:['dashboard','purchases','expenses','reports','crm'],
    warehouse:['dashboard','products','purchases','sales','settings'],
    staff:['dashboard','products','settings']
  };
  const order=primaryByRole[role]||['dashboard','products','settings'];
  const primary=order.map(id=>visible.find(n=>n.id===id)).filter(Boolean);
  const extras=visible.filter(n=>!primary.some(p=>p.id===n.id));
  const mobile=[...primary];if(extras.length)mobile.push({id:'__more',label:'Lainnya',mobileLabel:'Lainnya',icon:'•••'});
  $('#mobileNav').style.setProperty('--mobile-count',Math.max(mobile.length,1));
  $('#mobileNav').innerHTML=mobile.map(n=>n.id==='__more'?`<button data-mobile-more="1"><b>${n.icon}</b>${n.mobileLabel}</button>`:`<button class="${state.page===n.id?'active':''}" data-nav="${n.id}"><b>${n.icon}</b>${escapeHtml(role==='warehouse'&&n.id==='sales'?'Kirim':(n.mobileLabel||n.label))}</button>`).join('');
  $$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
  const more=$('[data-mobile-more]');if(more)more.onclick=()=>openMobileMoreMenu(extras);
};

