// ---------- Action & page binding wrappers ----------
const _handleActionBase=handleAction;
function handleV116Action(action,el){const id=el?.dataset?.id;if(action==='open-shift'){openShiftModal();return true}if(action==='close-shift'){closeShiftModal();return true}if(action==='cash-movement'){cashMovementModal();return true}if(action==='refund-sale'){refundModal(id);return true}if(action==='product-tab'){state.productTab=el.dataset.tab||'master';render();return true}if(action==='stock-opname'){stockOpnameModal(id);return true}if(action==='edit-recipe'){recipeModal(id);return true}if(action==='add-customer'){customerModal();return true}if(action==='edit-customer'){customerModal(id);return true}if(action==='loyalty-settings'){loyaltySettingsModal();return true}if(action==='crm-search'){viewFilters.crm.query=$('#crmSearch')?.value||'';render();return true}if(action==='crm-reset'){viewFilters.crm.query='';render();return true}return false}
handleAction=function(action,el){if(handleV116Action(action,el))return;return _handleActionBase(action,el)};
const _bindPageActionsBase=bindPageActions;
bindPageActions=function(){_bindPageActionsBase();const cs=$('#crmSearch');if(cs)cs.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();viewFilters.crm.query=cs.value;render()}}};

